1	import { execFileSync } from "node:child_process";
2	import { describe, it, expect } from "vitest";
3	import { ClaimOfficeError, runScenario } from "./claim-office.js";
4	
5	const runCli = (
6	  input: unknown,
7	): { stdout: string; stderr: string; status: number } => {
8	  try {
9	    const stdout = execFileSync("npx", ["tsx", "src/cli.ts"], {
10	      input: JSON.stringify(input),
11	      encoding: "utf8",
12	      stdio: ["pipe", "pipe", "pipe"],
13	    });
14	    return { stdout, stderr: "", status: 0 };
15	  } catch (error) {
16	    const failure = error as {
17	      stdout?: string;
18	      stderr?: string;
19	      status?: number;
20	    };
21	    return {
22	      stdout: failure.stdout ?? "",
23	      stderr: failure.stderr ?? "",
24	      status: failure.status ?? 1,
25	    };
26	  }
27	};
