29	describe("MHPCO Claim Office — quote", () => {
30	  // Simplest case
31	  it("empty item list → premium 5 G (only the processing fee)", () => {
32	    const scenario = {
33	      customer: { yearsWithMHPCO: 0 },
34	      steps: [{ op: "quote", items: [] }],
35	    };
36	
37	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
38	  });
39	
