54	
55	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
56	  });
57	  it("a single staff (base 80 G) for a newcomer → premium 93 G (80 + 8 + 5)", () => {
58	    const scenario = {
59	      customer: { yearsWithMHPCO: 0 },
60	      steps: [{ op: "quote", items: [{ type: "staff" }] }],
61	    };
62	
63	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
64	  });
65	  it("a single potion (base 40 G) for a newcomer → premium 49 G (40 + 4 + 5)", () => {
66	    const scenario = {
67	      customer: { yearsWithMHPCO: 0 },
68	      steps: [{ op: "quote", items: [{ type: "potion" }] }],
69	    };
70	
71	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 49 }] });
72	  });
73	
74	  // Components and the building block
75	  it("2 runes → 50 G base premium (newcomer, first quote: 50 + 5 + 5 = 60 G premium)", () => {
76	    const scenario = {
77	      customer: { yearsWithMHPCO: 0 },
78	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
79	    };
80	
81	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
82	  });
83	  it("3 runes → 60 G base premium, block applies (newcomer, first quote: 60 + 6 + 5 = 71 G premium)", () => {
84	    const scenario = {
85	      customer: { yearsWithMHPCO: 0 },
86	      steps: [
87	        {
88	          op: "quote",
89	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
90	        },
91	      ],
92	    };
93	
94	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
95	  });
96	  it("4 runes → 100 G base premium, no block since a block requires exactly 3 (newcomer, first quote: 100 + 10 + 5 = 115 G premium)", () => {
97	    const scenario = {
98	      customer: { yearsWithMHPCO: 0 },
99	      steps: [
100	        {
101	          op: "quote",
102	          items: [
103	            { type: "rune" },
104	            { type: "rune" },
